// fillet: a variable conic fillet (rho 0.7), 2 mm to 4 mm, along the concave edge of an L-shaped block
export function c006(context is Context, id is Id)
{
    const s1 = newSketchOnPlane(context, id + "s1", { "sketchPlane" : plane(vector(0, 0, 0) * millimeter, vector(1, 0, 0), vector(0, 1, 0)) });
    skLineSegment(s1, "l1", { "start" : vector(0, 0) * millimeter, "end" : vector(30, 0) * millimeter });
    skLineSegment(s1, "l2", { "start" : vector(30, 0) * millimeter, "end" : vector(30, 10) * millimeter });
    skLineSegment(s1, "l3", { "start" : vector(30, 10) * millimeter, "end" : vector(10, 10) * millimeter });
    skLineSegment(s1, "l4", { "start" : vector(10, 10) * millimeter, "end" : vector(10, 30) * millimeter });
    skLineSegment(s1, "l5", { "start" : vector(10, 30) * millimeter, "end" : vector(0, 30) * millimeter });
    skLineSegment(s1, "l6", { "start" : vector(0, 30) * millimeter, "end" : vector(0, 0) * millimeter });
    skSolve(s1);
    extrude(context, id + "base", { "entities" : qSketchRegion(id + "s1"), "endBound" : BoundingType.BLIND, "depth" : 40 * millimeter });
    fillet(context, id + "fillet1", { "entities" : qContainsPoint(qOwnedByBody(qBodyType(qCreatedBy(id + "base", EntityType.BODY), BodyType.SOLID), EntityType.EDGE), vector(20, 10, 10) * millimeter), "radius" : 3 * millimeter, "nonCircularRadius" : 3 * millimeter, "isVariable" : true, "crossSection" : FilletCrossSection.CONIC, "rho" : 0.7, "smoothTransition" : true, "vertexSettings" : [{ "vertex" : qContainsPoint(qOwnedByBody(qBodyType(qCreatedBy(id + "base", EntityType.BODY), BodyType.SOLID), EntityType.VERTEX), vector(0, 10, 10) * millimeter), "vertexRadius" : 2 * millimeter, "variableRho" : 0.7 }, { "vertex" : qContainsPoint(qOwnedByBody(qBodyType(qCreatedBy(id + "base", EntityType.BODY), BodyType.SOLID), EntityType.VERTEX), vector(40, 10, 10) * millimeter), "vertexRadius" : 4 * millimeter, "variableRho" : 0.7 }] });
    return { "faces" : faceProbe(context, qBodyType(qCreatedBy(id + "base", EntityType.BODY), BodyType.SOLID)) };
}

